    /// <summary>
    /// MPJ_2689_FixedAssetBalances
    /// </summary>
    public void processReport()
    {
        AssetBalances    assetBalances;
        QueryRun         queryRun;
        AssetBalancesTmp assetBalancesTmp = this.getAssetBalancesTmp();
        queryRun = new QueryRun(this.parmQuery());

        next processReport();

     

        while (queryRun.next())
        {
            assetBalances = queryRun.get(tablenum(AssetBalances));
            ttsbegin;
            select forupdate assetBalancesTmp
                    where assetBalancesTmp.AssetId == assetBalances.AssetId
                    &&    assetBalancesTmp.BookId  == assetBalances.BookId;
            {
                assetBalancesTmp.METServiceLife                     = assetBalances.ServiceLife;
                assetBalancesTmp.METLifeTimeRestYears               = (assetBalances.LifeTimeRest /12);
                assetBalancesTmp.METLifeTimeRest                    = assetBalances.LifeTimeRest;
                assetBalancesTmp.AcquisitionPriceReportingCurrency  = assetBalances.AcquisitionPriceReportingCurrency;
                assetBalancesTmp.update();
            }
            ttscommit;
        }
    }
